class InterruptableTaskSet(SequentialTaskSet):
    counter: DefaultDict[str, int] = defaultdict(int)

    def on_start(self):
        super().on_start()
        self.counter["on_start"] += 1

    @task
    def t1(self):
        self.counter["t1"] += 1
        self.interrupt(reschedule=False)

    @task
    def t2(self):
        self.counter["t2"] += 1

    def on_stop(self):
        super().on_stop()
        self.counter["on_stop"] += 1
        if self.counter["on_stop"] >= 2:
            raise StopUser()

